action.mutation:
mutation CreateProductionHistory($payload: [ProductionHistoryCreatePayloadInput!]!) {
  mutation: createProductionHistory(payload: $payload) { 
    id
    number
  }
}

mutation UpdateProductionHistory($payload: [ProductionHistoryUpdatePayloadInput!]!) {
  mutation: updateProductionHistory(payload: $payload) { 
    id
    number
  }
}
